864	        // 次回も復元されるよう、保存してある画像を新しい識別子でも保存する。
865	        void getBlob(worldPhoto.id)
866	          .then((blob) => (blob && this.worldPhotos.includes(copy) ? putBlob(copy.id, blob) : undefined))
867	          .catch((error: unknown) => {
868	            console.warn('[handFrame] 複製した写真の画像を保存できませんでした。次回は復元されません', error);
869	          });
870	        return copy.item;
871	      },
872	      setPose: (position, quaternion) => {
873	        if (this.app.items.holdersOf(item).length > 0) return;
874	        photo.position.copy(position);
875	        photo.quaternion.copy(quaternion);
876	      },
877	      grab: (hand, button) => this.app.holding.hold(hand, photo, button),
878	    };
879	    return item;
880	  }
