882	  /** 保存してあった写真を、画像を読み直して作り直す。 */
883	  private async restoreWorldPhotos(saved: SavedPhoto[]): Promise<void> {
884	    const session = this.app.session;
885	    for (const { id, width, height, pose } of saved) {
886	      const blob = await getBlob(id);
887	      // 撮った直後にページを閉じると、画像の保存が間に合っていないことがある。
888	      if (!blob) continue;
889	      const url = URL.createObjectURL(blob);
890	      try {
891	        const texture = await new THREE.TextureLoader().loadAsync(url);
892	        // 読み込みを待つ間に、セッションが終わったり「全部消す」が押されたりしていたら、作らない。
893	        if (this.app.session !== session || this.restoreGeneration !== this.clearGeneration) {
894	          texture.dispose();
895	          return;
896	        }
897	        this.app.persistence.place(this.createWorldPhoto(id, texture, width, height).group, pose);
898	      } finally {
899	        URL.revokeObjectURL(url);
900	      }
901	    }
902	  }
903	
904	  private clearWorldPhotos(): void {
905	    this.clearGeneration++;
906	    for (const photo of this.worldPhotos) this.removeWorldPhoto(photo);
907	    this.worldPhotos.length = 0;
908	  }
909	
910	  /** keepImage: 保存してある画像を残す (セッションの終了で、表示だけ片付けるとき) */
911	  private removeWorldPhoto({ id, group: photo, item }: WorldPhoto, keepImage = false): void {
912	    if (!keepImage) void deleteBlob(id).catch(() => {});
913	    this.app.scene.remove(photo);
914	    this.app.holding.remove(photo);
915	    this.app.items.unregister(item);
916	    for (const child of photo.children) {
